export const fetchCarbonData = async () => {
    try {
      const querySnapshot = await getDocs(collection(db, "carbon-emissions"));
      return querySnapshot.docs.map((doc) => doc.data());
    } catch (error) {
      console.error("Error fetching carbon data:", error);
      return [];
    }
  };

  export const calculateMonthlyAverages = (data) => {
    const monthlySums = Array(12).fill(0);
    const monthlyCounts = Array(12).fill(0);

    data.forEach((record) => {
      if (record.createdAt && record.totalCarbon) {
        const date = record.createdAt.toDate(); // Convert Firestore Timestamp to Date
        const month = date.getMonth();
        monthlySums[month] += record.totalCarbon;
        monthlyCounts[month] += 1;
      }
    });

    return monthlySums.map((sum, i) => (monthlyCounts[i] > 0 ? sum / monthlyCounts[i] : 0));
  };
